
export type LocaleTopLevelDomain = 'es' | 'se' | 'dk' | 'it' | 'co.uk';
export type Locale = 'en-gb' | 'it-it' | 'es-es' | 'dk-dk' | 'se-se';

export type IPoweredByTombolaEnvironment = 'dev' | 'integration' | 'production';
export type IPoweredByTombolaOperator = ('tombola' | 'sisal' | 'snai');

export type Environment = 'debug' | 'dev' | 'stage' | 'live';

/**
 * @description Type Wrapper to be used on an interface to force all properties specified to become optional
 */
export type PickPartial<T, TKeys extends keyof T> = Omit<T, TKeys> & Pick<Partial<T>, TKeys>;
/**
 * @description Type Wrapper to be used on an interface to force all properties specified to become required
 */
export type PickRequired<T, TKeys extends keyof T> = Omit<T, TKeys> & Pick<Required<T>, TKeys>;
/**
 * @description Type Wrapper to be used on an interface to force all properties to be required except those that are specified to become optional
 */
export type RequiredWithPickPartial<T, TKeys extends keyof T> = Required<Omit<T, TKeys>> & Partial<Pick<T, TKeys>>;
/**
 * @description Type Wrapper to be used on an interface to force all properties to be optional except those that are specified to become required
 */
export type PartialWithPickRequired<T, TKeys extends keyof T> = Required<Pick<T, TKeys>> & Partial<Omit<T, TKeys>>;

type BaseExtendAndOverwrite<T extends object, U extends object> = Pick<T, Exclude<keyof T, keyof U>> & U;
type RemoveableKeys<T extends object, U extends object> = keyof Pick<T, Exclude<keyof T, keyof U>>;

/**
 * @description Utility Type to combine interfaces by overwriting existing property types with the optional ability to remove the original interface's unique properties
 */
export type ExtendAndOverwrite<T extends object, U extends object, Keys extends RemoveableKeys<T, U> = never> =
    [Keys] extends [never] ? BaseExtendAndOverwrite<T, U> : Omit<BaseExtendAndOverwrite<T, U>, Keys>;

export type DeepPartial<T> = T extends object ? {
    [P in keyof T]?: DeepPartial<T[P]>
} : T;

type DeepWriteable<T> = { -readonly [P in keyof T]: DeepWriteable<T[P]> };
// eslint-disable-next-line @typescript-eslint/ban-types
type ExcludeMethods<T> = Pick<T, { [K in keyof T]: T[K] extends Function ? never : K }[keyof T]>;
type DeepExcludeMethods<T> = { [P in keyof ExcludeMethods<T>]: T[P] extends object ? DeepExcludeMethods<ExcludeMethods<T>[P]> : T[P] };

/**
 * @description We can use this type wrapper for turning any class into a lump of state,
 * removing all method defintions from the type and turning all readonly properties into writeables
 */
export type Statify<T> = DeepWriteable<DeepExcludeMethods<T>>;

export type EnvironmentConfigItem<T> = {
    [key in Environment]: T;
};
export interface IVersion {
    major: number;
    minor: number;
    patch: number;
    build: number;
}

export interface IDebounceOptions {
    leading?: boolean;
    maxWait?: number;
    trailing?: boolean;
}

export interface IThrottleOptions {
    leading?: boolean;
    trailing?: boolean;
}

export interface IXmlNode<Attributes extends IBaseXmlNodeAttributes = IBaseXmlNodeAttributes, ChildNodes extends IXmlChildNodes = IXmlChildNodes> {
    name: string;
    attributes: Attributes;
    childNodes: ChildNodes;
}

interface IBaseXmlNodeAttributes {
    [key: string]: string | undefined;
}

export type IXmlNodeAttributes<T extends object = object> = T & IBaseXmlNodeAttributes;

export interface IXmlChildNodes {
    [key: string]: IXmlNode[];
}

interface IOptionalXmlChildNodes {
    [key: string]: IOptionalXmlNode[];
}

export type IOptionalXmlNode<Attributes extends IBaseXmlNodeAttributes = IBaseXmlNodeAttributes> = ExtendAndOverwrite<IXmlNode, {
    attributes?: Attributes;
    childNodes?: IOptionalXmlChildNodes;
}>;

export interface IObjectMap { [key: string]: any; }
